<script lang="ts">
 import {onMount} from 'svelte';
 import {base} from '$app/paths';
 import {houses,proposedCards} from '$lib/expansion/cards';
 import type {CardFaceDefinition} from '$lib/game/types';
 import PrototypeCard from '$lib/components/expansion/PrototypeCard.svelte';
 import EffectIcon from '$lib/components/expansion/EffectIcon.svelte';
 import DialogFrame from '$lib/components/DialogFrame.svelte';
 import CardLayoutReport from '$lib/components/CardLayoutReport.svelte';
 function openDialog(node:HTMLDialogElement){node.showModal();}
 let tab=$state('gallery'),houseFilter=$state('Zeus'),inspected=$state<CardFaceDefinition|null>(null),checks=$state(false),grid=$state<HTMLDivElement>();
 const help:Record<string,string>={Echo:'Borrow an Action from an opponent’s discard. If empty, discard their top deck card and play its effect if any. Return borrowed cards at cleanup.',Seek:'Reveal N from your deck, keep up to one matching card in hand, and discard the rest. Held reveals are excluded from shuffles.',Deploy:'Play the next Action, Treasure or Territory for free and resolve it N times. Each Territory activation draws one card. Each grant applies independently, in order. Treasures and Territories keep the current phase and grant no Devotion; Actions grant Devotion once. Favored Nike worship grants Deploy 3.',Bind:'Topdeck up to N Territories from opponents’ discards onto their owners’ decks, in your chosen order.'};
 function view(next:string){tab=next;history.replaceState(null,'',next==='lab'?'#lab':'#gallery');}
 onMount(()=>{if(location.hash==='#lab')location.replace(base+'/dev/animations/?scenario=expansion-ariadnes-thread');});
</script>
<svelte:head><title>Divine houses · Pantheon: Bloodlines</title><meta name="robots" content="noindex"/></svelte:head>
<div class="shell" style:--table-art={`url('${base}/assets/ui/table-desktop.webp')`}>
<header><a class="brand" href={`${base}/`}>PANTHEON <span>BLOODLINES</span></a><div class="heading"><div><p class="eyebrow">THE NEXT CHAPTER</p><h1>Four divine houses</h1></div><p class="review-note">Visual review<br/><span>New cards & effects · rules under review</span></p></div></header>
<nav class="view-tabs" aria-label="Preview views"><button class:chosen={tab==='gallery'} onclick={()=>view('gallery')}>Card collection <small>24</small></button><a href={`${base}/expansion/`}>Play expansion ↗</a><a href={`${base}/dev/animations/?scenario=expansion-ariadnes-thread`}>Animation lab ↗</a></nav>
{#if tab==='gallery'}
 <div class="house-tabs" aria-label="Choose a divine house">{#each houses as house}<button class:chosen={houseFilter===house.god} style:--accent={house.color} onclick={()=>houseFilter=house.god}><img src={`${base}/assets/expansion/cards/${house.leader.toLowerCase()}.webp`} alt=""/><span><strong>{house.leader}</strong><small>{house.god}</small></span></button>{/each}</div>
 <div bind:this={grid}>
 {#each houses.filter(h=>houseFilter===h.god) as house}
  {@const collection=proposedCards.filter(c=>c.god===house.god)}
  <section class="collection" style:--accent={house.color}>
   <div class="collection-heading"><div><p class="eyebrow">HOUSE OF {house.god.toUpperCase()}</p><h2>{house.theme}</h2></div><span>1 leader · 1 worship · 4 deck cards</span></div>
   <div class="sovereigns">{#each collection.filter(c=>c.type==='Leader'||c.type==='Event') as card}<figure><button class="card-button" onclick={()=>inspected=card} aria-label={`Inspect ${card.name}`}><PrototypeCard {card}/></button><figcaption>{card.type==='Leader'?'YOUR BLOODLINE':'SHARED WORSHIP'} <span>{card.name}</span></figcaption></figure>{/each}</div>
   <div class="deck-cards">{#each collection.filter(c=>c.type==='Action') as card}<figure><button class="card-button" onclick={()=>inspected=card} aria-label={`Inspect ${card.name}`}><PrototypeCard {card}/></button><figcaption>{card.uniqueStartingCard?'STARTING TEMPLE':`${card.cost} COINS`} <span>{card.name}</span></figcaption></figure>{/each}</div>
  </section>
 {/each}
 </div>
 <section class="legend" aria-label="New effect icons">{#each ['Echo','Seek','Deploy','Bind'] as effect}<article><EffectIcon {effect} value={effect==='Deploy'?3:effect==='Echo'?2:1} positive={effect==='Echo'}/><div><h3>{effect}</h3><p>{help[effect]}</p></div></article>{/each}</section>
 <details class="verification" bind:open={checks}><summary>Card layout diagnostics</summary>{#if checks}<CardLayoutReport root={grid}/>{/if}</details>
{/if}
<footer><span>FOUR HOUSES. TWELVE ACTION PILES.</span><p>Drafted houses are joined by random undrafted houses as needed. Only drafted leaders bring their Temple and worship event. New mechanics remain in this review environment until approved.</p></footer>
</div>
{#if inspected}<dialog class="framed-dialog inspector" use:openDialog aria-label={inspected.name} onclose={()=>inspected=null}><DialogFrame/><button class="close" onclick={()=>inspected=null} aria-label="Close card inspection">×</button><div class="large" class:landscape={inspected.type==='Leader'||inspected.type==='Event'}><PrototypeCard card={inspected}/></div><div class="transcript"><p class="eyebrow">{inspected.god} · {inspected.type}</p><h2>{inspected.name}</h2><p>{inspected.effect}</p>{#if inspected.favored}<p><strong>Favored:</strong> {inspected.favored}</p>{/if}{#each Object.keys(help).filter(effect=>inspected?.effect.includes(effect)||inspected?.favored?.includes(effect)) as effect}<p class="reminder"><strong>{effect}.</strong> {help[effect]}</p>{/each}</div></dialog>{/if}
